        x = frontier.pop()
        for g, hg in zip(gens, images):
            y = G.mul(x, g)
            hy = H.mul(phi[x], hg)
            if y in phi:
                if phi[y] != hy:
                    return None
            else:
                phi[y] = hy
                frontier.append(y)
