            print(f"  Hom({G.name:>4}, {H.name:>7}): "
                  f"{total:>3} pointed classes = {len(orbits):>3} unpointed "
                  f"classes  (all fibres of size 1)")


def demo_self_equivalences() -> None:
    """Pointed self-equivalences = Aut G;  unpointed = Out G."""
    print("\n=== Self-equivalences of K(G,1):  Aut G  versus  Out G ==")
    print(f"{'G':>8} {'|G|':>4} {'|Aut G|':>8} {'|Inn G|':>8} "
          f"{'|Out G|':>8} {'[G:Z(G)]':>9}")
    for G in [cyclic(1), cyclic(2), cyclic(4), cyclic(6), klein_four(),
              symmetric(3), dihedral(4), cyclic(8), symmetric(4)]:
        aut = len(automorphisms(G))
        inn = len(inner_automorphisms(G))
        idx = G.order // len(G.centre())
        assert inn == idx, "Inn G is not G/Z(G)"
        print(f"{G.name:>8} {G.order:>4} {aut:>8} {inn:>8} "
              f"{aut // inn:>8} {idx:>9}")
    print("The fibre of  Aut G  ->  Out G  over the identity class has "
          "[G:Z(G)] elements,")
    print("exactly the general fibre count applied to phi = id.")


def demo_strict_functoriality() -> None:
    """Composition of pointed classes is composition of homomorphisms, on the nose."""
    print("\n=== Strict functoriality of the pointed classification ==")
    S3 = symmetric(3)
    homs = all_homomorphisms(S3, S3)
    bad = 0
    for phi in homs:
        for psi in homs:
            comp = {g: psi[phi[g]] for g in S3.elements}
            # composition of pointed classes = composition of homomorphisms
            if any(comp[S3.mul(a, b)] != S3.mul(comp[a], comp[b])
                   for a in S3.elements for b in S3.elements):
                bad += 1
    print(f"checked {len(homs)**2} composites of pointed classes; "
          f"failures: {bad}")
    assert bad == 0
    print("By contrast, unpointed composition is only well defined on")
    print("conjugacy classes: the induced homomorphism of a composite is")
    print("merely CONJUGATE to the composite of the induced homomorphisms.")
    # exhibit the unpointed ambiguity concretely
    orbits = conjugation_orbits(S3, S3)
    reps = [dict(o[0]) for o in orbits]
    print("Composition table of the three unpointed classes "
          "(monoid of conjugacy classes of endomorphisms):")
    labels = {freeze(r, S3): i for i, o in enumerate(orbits) for r in [dict(x) for x in o]}
    for i, a in enumerate(reps):
        row = []
        for j, b in enumerate(reps):
            comp = {g: b[a[g]] for g in S3.elements}
            row.append(labels[freeze(comp, S3)])
        print(f"   class {i} composed with each class -> {row}")


def main() -> None:
    print("=" * 60)
    print("Pointed and unpointed classification of maps of 1-types")
    print("=" * 60)
    demo_s3_test()
    demo_fibre_theorem(symmetric(3), symmetric(3))
    demo_fibre_theorem(cyclic(6), symmetric(3))
    demo_fibre_theorem(symmetric(3), dihedral(4))
    demo_fibre_theorem(klein_four(), symmetric(4))
    demo_abelian_case()
    demo_self_equivalences()
    demo_strict_functoriality()
    print("\nAll assertions passed.")


if __name__ == "__main__":
    main()

"""
Pointed versus unpointed self-map monoids of K(G,1).

For a connected 1-type with fundamental group G:

  * POINTED self-map classes form a monoid isomorphic to End(G);
    its unit group is Aut(G)  (pointed Whitehead theorem).
  * UNPOINTED self-map classes form the monoid of CONJUGACY CLASSES of
    endomorphisms of G; its unit group is Out(G) = Aut(G)/Inn(G).

This script builds both monoids explicitly for G = S_3, prints their
multiplication tables, checks that the quotient map is a monoid homomorphism,
and verifies that the fibre over the identity class has [G:Z(G)] = 6 elements.
"""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Tuple

Perm = Tuple[int, ...]

ONE: Perm = (0, 1, 2)
S3: List[Perm] = [(0, 1, 2), (0, 2, 1), (1, 0, 2), (1, 2, 0), (2, 0, 1), (2, 1, 0)]


def mul(p: Perm, q: Perm) -> Perm:
    """(p*q)(i) = p(q(i))."""
    return tuple(p[q[i]] for i in range(3))


def inv(p: Perm) -> Perm:
    return next(q for q in S3 if mul(p, q) == ONE)


def is_hom(phi: Dict[Perm, Perm]) -> bool:
    return all(phi[mul(a, b)] == mul(phi[a], phi[b]) for a in S3 for b in S3)


def all_endomorphisms() -> List[Dict[Perm, Perm]]:
    """S_3 is generated by (0 1) and (0 1 2); lift both and test."""
    g1, g2 = (1, 0, 2), (1, 2, 0)
    out: List[Dict[Perm, Perm]] = []
    for h1, h2 in product(S3, repeat=2):
        phi: Dict[Perm, Perm] = {ONE: ONE}
        frontier = [ONE]
        ok = True
        while frontier and ok:
            x = frontier.pop()
            for g, h in ((g1, h1), (g2, h2)):
                y, hy = mul(x, g), mul(phi[x], h)
                if y in phi:
                    if phi[y] != hy:
                        ok = False
                        break
                else:
                    phi[y] = hy
                    frontier.append(y)
        if ok and len(phi) == 6 and is_hom(phi):
            out.append(phi)
    return out


def key(phi: Dict[Perm, Perm]) -> Tuple[Perm, ...]:
    return tuple(phi[g] for g in S3)


def conjugate(u: Perm, phi: Dict[Perm, Perm]) -> Dict[Perm, Perm]:
    ui = inv(u)
    return {g: mul(mul(u, h), ui) for g, h in phi.items()}


def compose(phi: Dict[Perm, Perm], psi: Dict[Perm, Perm]) -> Dict[Perm, Perm]:
    """psi after phi."""
    return {g: psi[phi[g]] for g in S3}


def main() -> None:
    ends = all_endomorphisms()
    print(f"|End(S_3)| = {len(ends)}   (= pointed self-map classes of K(S_3,1))")
    assert len(ends) == 10

    auts = [p for p in ends if len(set(p.values())) == 6]
    print(f"|Aut(S_3)| = {len(auts)}   (= pointed self-EQUIVALENCE classes)")
    assert len(auts) == 6

    # conjugacy classes of endomorphisms = unpointed classes
    classes: List[List[Tuple[Perm, ...]]] = []
    seen: set = set()
    for phi in ends:
        if key(phi) in seen:
            continue
        orbit = sorted({key(conjugate(u, phi)) for u in S3})
        seen |= set(orbit)
        classes.append(orbit)
    classes.sort(key=len)
    print(f"unpointed self-map classes = {len(classes)}, "
          f"fibre sizes = {[len(c) for c in classes]}")
    assert [len(c) for c in classes] == [1, 3, 6]

    label = {k: i for i, c in enumerate(classes) for k in c}
    names = {0: "constant", 1: "sign-and-swap", 2: "identity-like (automorphisms)"}

    print("\nPointed monoid End(S_3): 10 x 10 table (entries indexed 0..9)")
    idx = {key(p): i for i, p in enumerate(ends)}
    for i, a in enumerate(ends):
        row = [idx[key(compose(a, b))] for b in ends]
        print(f"  {i:>2}: {row}")

    print("\nUnpointed monoid (3 elements), induced on conjugacy classes:")
    reps = [dict(zip(S3, c[0])) for c in classes]
    for i, a in enumerate(reps):
        row = [label[key(compose(a, b))] for b in reps]
        print(f"  {names[i]:>32} -> {row}")

    print("\nWell-definedness check: composition descends to conjugacy classes")
    bad = 0
    for a in ends:
        for b in ends:
            for u in S3:
                for v in S3:
                    if label[key(compose(conjugate(u, a), conjugate(v, b)))] \
                            != label[key(compose(a, b))]:
                        bad += 1
    print(f"  violations: {bad}")
    assert bad == 0

    centre = [x for x in S3 if all(mul(x, y) == mul(y, x) for y in S3)]
    print(f"\nZ(S_3) has order {len(centre)}, so [S_3 : Z(S_3)] = {6 // len(centre)}")
    print("  = the number of pointed classes over the unpointed identity class = 6,")
    print("  = |Inn(S_3)| = kernel of Aut(S_3) -> Out(S_3), and Out(S_3) is trivial.")
    print("\nAll assertions passed.")


if __name__ == "__main__":
    main()

